package dataaccess.sql;

import dataaccess.DataAccessException;
import dataaccess.DatabaseManager;
import dataaccess.UserDAO;
import model.UserData;
import org.mindrot.jbcrypt.BCrypt;

import java.sql.SQLException;

public class SqlUserDAO implements UserDAO {

    public SqlUserDAO() throws DataAccessException {
        configureDatabase();
    }

    // Method implementations autogenerated by intelliJ
    @Override
    public UserData getUser(String username) throws DataAccessException {
        return null;
    }

    @Override
    // thanks, masteryls jdbc.
    public void createUser(UserData userData) throws DataAccessException {

        // hash the password
        String hash = BCrypt.hashpw(userData.password(), BCrypt.gensalt());

        // create a connection.
        try (var conn = DatabaseManager.getConnection()) {
            // create a prepared statement
            var statement = "INSERT INTO user (username, password, email) VALUES (?, ?, ?)";
            // insert username, password hash, email.
            try (var preparedStatement = conn.prepareStatement(statement)) {
                preparedStatement.setString(1, userData.username());
                preparedStatement.setString(2, hash);
                preparedStatement.setString(3, userData.email());

                preparedStatement.executeUpdate();
            }

        } catch (SQLException ex) {
            throw new DataAccessException("Error: issue adding new user.");
        }
    }

    @Override
    public void removeUsers() throws DataAccessException {

    }

    // pet shop helping me out with this, as well as MasteryLS "JDBC"
    private void configureDatabase() throws DataAccessException {
        DatabaseManager.createDatabase();
        // connect to database.
        try (var conn = DatabaseManager.getConnection()) {

            // syntax from pet shop mysqldataaccess.java
            final String createTableStatement = """
                    CREATE TABLE IF NOT EXISTS user (
                        username VARCHAR(255) NOT NULL,
                        password VARCHAR(255) NOT NULL,
                        email VARCHAR(255) NOT NULL,
                        PRIMARY KEY (username)
                    );
                    """;

            // create a prepared statement using the create table statement. Execute it.
            try (var preparedStatement = conn.prepareStatement(createTableStatement)) {
                preparedStatement.executeUpdate();
            }
        } catch (SQLException e) {  // throw a DataAccessException instead of the SQL exception.
            throw new DataAccessException("Unable to configure user storage.");
        }
    }

}
